/**
 * Loot economy report: lets bots play for hours and prints, per simulated hour, what dropped and what it was worth.
 *
 *   node scripts/loot-report.ts [hours=6] [seeds=1,2,3] [builds=fire,cold,storm,wfire,wcold,wstorm]
 *   node scripts/loot-report.ts 4 1,2 fire,wcold --rift 10      end-game hero (level 60) in auto rift mode from tier 10
 *   add --hourly to print every single run hour by hour, --csv for machine-readable rows
 *
 * Columns: N/M/R/U = equipment generated by rarity (all sources), shown = kept by the loot rules (lies on the ground),
 * salv = salvaged on the spot, U src = uniques by source, ups = found upgrades equipped, cup = crafts that made an equipped item stronger, crafts = all crafts,
 * mats = materials gained (salvage + direct drops), dust/ess/shard/pearl.
 */
import { AREAS, DIFFICULTIES, MAT_IDS, type Mats } from '../src/content/index.ts';
import { Sim } from '../src/sim/sim.ts';
import { newSaveState } from '../src/sim/state.ts';
import { rollKey } from '../src/sim/rift.ts';
import type { LootStats } from '../src/sim/drops.ts';
import { Bot } from './bot.ts';
import { endgameSave, planClass } from './endgame.ts';

const args = process.argv.slice(2), flag = (k: string) => { const i = args.indexOf(k); if (i < 0) return null; const v = args[i + 1]; args.splice(i, 2); return v; };
const bool = (k: string) => { const i = args.indexOf(k); if (i < 0) return false; args.splice(i, 1); return true; };
const riftStart = flag('--rift'), hourly = bool('--hourly'), csv = bool('--csv');
const hours = Number(args[0] ?? 6), seeds = (args[1] ?? '1,2,3').split(',').map(Number), builds = (args[2] ?? 'fire,cold,storm,wfire,wcold,wstorm').split(',');

interface Hour {
  stage: string; lvl: number; deaths: number; kills: number; gen: number[]; shown: number[]; salv: number;
  uniq: Record<string, number>; src: Record<string, number[]>; ups: number; cups: number; crafts: number; mats: Mats; gold: number; tier: number; offClass: number;
}

const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
const add = (a: number[], b: number[]) => a.map((x, i) => x + (b[i] || 0));
const stageOf = (sim: Sim) => sim.rift.run ? `Rift T${sim.rift.run.tier}` : `${DIFFICULTIES[sim.s.difficulty].name.slice(0, 2)} ${AREAS[sim.s.zone].name.replace(/^The /, '').split(' ')[0]}`;

function play(build: string, seed: number): Hour[] {
  const rift = riftStart != null;
  const sim = new Sim(rift ? endgameSave(build, 60, seed) : newSaveState(planClass(build)), { seed, headless: true });
  const bot = new Bot(sim, build, { rift });
  if (rift) {
    sim.s.rift.auto = true;
    sim.takeItem(rollKey(sim.rng, sim.itemId(), Number(riftStart)), true);
    sim.s.rift.maxTier = Math.max(0, Number(riftStart) - 1);
    sim.rift.startKey(sim.rift.bestKey()!.id);
  }
  const out: Hour[] = [];
  const cls = planClass(build);
  for (let h = 0; h < hours; h++) {
    sim.loot.resetStats();
    const d0 = sim.s.deaths, k0 = sim.s.kills, u0 = bot.upgrades, cu0 = bot.craftUps, c0 = Object.values(bot.crafts).reduce((a, b) => a + b, 0), g0 = sim.s.gold;
    let off = 0;
    const seen = new Set<number>();
    for (let t = 0; t < 3600; t += 5) {
      sim.advance(5);
      // class check: weapons and class uniques on the ground or in the bag must fit the hero's class
      for (const it of sim.s.bag) if ('slot' in it && !seen.has(it.id)) { seen.add(it.id); if (sim.loot.offClass(it, cls)) off++; }
      bot.step();
    }
    const L: LootStats = sim.loot.stats;
    const gen = Object.values(L.gen).reduce((a, b) => add(a, b!), [0, 0, 0, 0]);
    out.push({
      stage: stageOf(sim), lvl: sim.s.lvl, deaths: sim.s.deaths - d0, kills: sim.s.kills - k0, gen, shown: L.fate.keep.slice(), salv: sum(L.fate.salvage),
      uniq: { ...L.uniques } as Record<string, number>, src: structuredClone(L.gen) as Record<string, number[]>, ups: bot.upgrades - u0, cups: bot.craftUps - cu0, crafts: Object.values(bot.crafts).reduce((a, b) => a + b, 0) - c0,
      mats: sim.loot.matsGained(), gold: sim.s.gold - g0, tier: sim.s.rift.maxTier, offClass: off,
    });
  }
  return out;
}

const fmtR = (a: number[]) => a.map(x => (Math.round(x * 10) / 10).toString().padStart(5)).join(' ');
const fmtM = (m: Mats) => MAT_IDS.map(k => String(Math.round(m[k] || 0)).padStart(5)).join(' ');
const head = `  h  lvl  stage              kills  dth |  gen N     M     R     U | shown N    M     R     U |  salv  ups  cup crafts | ${MAT_IDS.map(k => k.slice(0, 5).padStart(5)).join(' ')} | uniques by source`;
function line(h: string, x: Hour) {
  const us = Object.entries(x.uniq).map(([k, v]) => `${k} ${Math.round(v * 10) / 10}`).join(', ');
  return `${h.padStart(3)}  ${String(Math.round(x.lvl)).padStart(3)}  ${x.stage.padEnd(17)} ${String(Math.round(x.kills)).padStart(6)} ${(Math.round(x.deaths * 10) / 10).toString().padStart(4)} | ${fmtR(x.gen)} | ${fmtR(x.shown)} | ${String(Math.round(x.salv)).padStart(5)} ${(Math.round(x.ups * 10) / 10).toString().padStart(4)} ${(Math.round(x.cups * 10) / 10).toString().padStart(4)} ${String(Math.round(x.crafts)).padStart(6)} | ${fmtM(x.mats)} | ${us}${x.offClass ? ` · OFF-CLASS ${x.offClass}` : ''}`;
}

for (const build of builds) {
  const runs = seeds.map(seed => play(build, seed));
  if (csv) {
    runs.forEach((r, si) => r.forEach((x, h) => console.log([build, seeds[si], h + 1, x.lvl, x.stage, x.kills, x.deaths, ...x.gen, ...x.shown, x.salv, x.ups, x.cups, x.crafts, ...MAT_IDS.map(k => x.mats[k] || 0), sum(Object.values(x.uniq))].join(','))));
    continue;
  }
  console.log(`\n=== ${build} (${planClass(build)}) · ${hours} h · seeds ${seeds.join(',')}${riftStart != null ? ` · rift from tier ${riftStart}` : ''} ===`);
  console.log(head);
  if (hourly) runs.forEach((r, si) => { console.log(`  seed ${seeds[si]}`); r.forEach((x, h) => console.log(line(String(h + 1), x))); });
  // average per hour over the seeds
  console.log('  average over seeds:');
  for (let h = 0; h < hours; h++) {
    const xs = runs.map(r => r[h]), n = xs.length, avg = (f: (x: Hour) => number) => xs.reduce((a, x) => a + f(x), 0) / n;
    const uniq: Record<string, number> = {};
    for (const x of xs) for (const [k, v] of Object.entries(x.uniq)) uniq[k] = (uniq[k] || 0) + v / n;
    const mats: Mats = {};
    for (const x of xs) for (const k of MAT_IDS) mats[k] = (mats[k] || 0) + (x.mats[k] || 0) / n;
    console.log(line(String(h + 1), {
      stage: xs.map(x => x.stage).sort((a, b) => xs.filter(y => y.stage === b).length - xs.filter(y => y.stage === a).length)[0] + (riftStart != null ? ` (best ${Math.round(avg(x => x.tier))})` : ''),
      lvl: avg(x => x.lvl), deaths: avg(x => x.deaths), kills: avg(x => x.kills), gen: [0, 1, 2, 3].map(i => avg(x => x.gen[i])), shown: [0, 1, 2, 3].map(i => avg(x => x.shown[i])),
      salv: avg(x => x.salv), uniq, src: {}, ups: avg(x => x.ups), cups: avg(x => x.cups), crafts: avg(x => x.crafts), mats, gold: avg(x => x.gold), tier: avg(x => x.tier), offClass: xs.reduce((a, x) => a + x.offClass, 0),
    }));
  }
  // equipment per source and hour (N/M/R/U), averaged over all hours and seeds
  const srcs: Record<string, number[]> = {};
  for (const r of runs) for (const x of r) for (const [k, v] of Object.entries(x.src)) srcs[k] = add(srcs[k] ?? [0, 0, 0, 0], v.map(y => y / (runs.length * hours)));
  console.log('  per hour by origin (N/M/R/U): ' + Object.entries(srcs).map(([k, v]) => `${k} ${v.map(y => Math.round(y * 10) / 10).join('/')}`).join(' · '));
  const tot = (f: (x: Hour) => number) => runs.reduce((a, r) => a + r.reduce((b, x) => b + f(x), 0), 0) / runs.length;
  console.log(`  per run: ${Math.round(tot(x => sum(x.gen)))} items, ${Math.round(tot(x => sum(x.shown)))} shown, ${tot(x => x.gen[3]).toFixed(1)} uniques, ${tot(x => x.ups).toFixed(1)} found upgrades, ${tot(x => x.cups).toFixed(1)} crafted upgrades, ${Math.round(tot(x => x.crafts))} crafts, ${tot(x => x.deaths).toFixed(1)} deaths, final level ${(runs.reduce((a, r) => a + r[r.length - 1].lvl, 0) / runs.length).toFixed(1)}`);
}
